     padding: 20px;
     margin-top: 20px;
     margin-bottom: 20px;
     border: 1px solid #e8e8e8;
}
.comment-author img {
     margin-right: 10px;
}
.commentslist .reply {
     display: inline-block;
     padding: 5px 15px;
     border: 1px solid #605be5;
}
.comment-form-comment input, .comment-form-comment textarea {
     border-color: #e8e8e8;
}
 nav.navigation {
     text-align: center;
}
 nav.navigation a, nav.navigation span {
     padding: 5px 10px;
     border: 1px solid #e8e8e8;
}
.footer-copyright {
     text-align: center;
     padding: 30px 0;
}
.site-logo a,
.main-navigation a,
.re-theme-post .read-more a,
.re-theme-post .post-title a {
	text-decoration: none;
}

/* Header Menu */
.rek-menu .menu-item {
	position: relative;
}

.rek-menu .menu-item-has-children > a:after {
	content: "\25BC";
	font-size: 8px;
	margin-left: 5px;
}

.rek-menu .menu-item-has-children:hover > .sub-menu {
	display: block;
}

.rek-menu .sub-menu {
	display: none;
	position: absolute;
	top: 100%;
	z-index: 9999;
	min-width: 200px;
	margin-left: 0;
	padding: 10px;
	background-color: #fff;
	box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}

.rek-menu .sub-menu li {
	margin-left: 0;
}

.rek-menu .sub-menu .sub-menu {
	top: 0;
	left: 100%;
	margin-left: 1px;
}




